import { readdirSync } from "node:fs";
import { join } from "node:path";
import { isListedModule } from "../listed.ts";

const GENERATED_HEADER = "// Generated by @slotform/node — do not edit.";

function servicesDir(cwd: string): string {
	return join(cwd, "src", "server", "services");
}

// The barrel is tracked in the consumer's tree: docs/architecture/codegen.md, "Tracked generated files".
const LINE_WIDTH = 80;

function renderServices(identifiers: string[]): string {
	const inline = `export const services = [${identifiers.join(", ")}];`;
	if (inline.length <= LINE_WIDTH) return inline;
	const lines = identifiers.map((identifier) => `\t${identifier},`).join("\n");
	return `export const services = [\n${lines}\n];`;
}

// The services directory layout: docs/architecture/plugins/node.md, "Services".
// A missing services directory (or a path component that is a file) holds no
// services; any other read error stops the generate.
function serviceFiles(cwd: string): string[] {
	try {
		return readdirSync(servicesDir(cwd)).filter(isListedModule).sort();
	} catch (error) {
		if (
			error instanceof Error &&
			"code" in error &&
			(error.code === "ENOENT" || error.code === "ENOTDIR")
		) {
			return [];
		}
		throw error;
	}
}

// Each import is named by its position, so any file name gives a valid,
// unique binding.
export function generateServiceBarrel(cwd: string): string {
	const files = serviceFiles(cwd);
	const identifiers = files.map((_, i) => `service${i}`);
	const imports = files
		.map((file, i) => `import ${identifiers[i]} from "./${file}";`)
		.join("\n");
	return `${GENERATED_HEADER}\n${imports}\n\n${renderServices(identifiers)}\n`;
}

export function hasServiceFiles(cwd: string): boolean {
	return serviceFiles(cwd).length > 0;
}
